xpath.script:
(function() {
    var isAgent = ;

    function toggleAgentMenu() {
        var links = document.querySelectorAll('a[href="/agent/shop"]');
        links.forEach(function(link) {
            var menuItem = link.closest('li');
            if (menuItem) {
                if (isAgent) {
                    menuItem.style.display = '';
                } else {
                    menuItem.style.display = 'none';
                }
            }
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', toggleAgentMenu);
    } else {
        toggleAgentMenu();
    }

    var observer = new MutationObserver(toggleAgentMenu);
    observer.observe(document.body, { childList: true, subtree: true });
})();
